import pandas as pd
import numpy as np

df = pd.read_csv('artifacts/exp-007/data/exp007_ppci_dsl.csv')

# The paper claims: 0.179 (naive), 0.007 (EC-HTE+PPCI), 0.092 (PPCI alone), 0.064 (EC-HTE alone)
# Let's check all configurations for C_both_errors
c_both = df[df['dgp'] == 'C_both_errors']

print('All C_both_errors configurations:')
for regime in ['extreme', 'moderate', 'homogeneous']:
    for k in [2, 4]:
        for n in [50, 100, 250, 500]:
            sub = c_both[(c_both['regime'] == regime) & (c_both['k_subgroups'] == k) & (c_both['n_expert'] == n)]
            if len(sub) == 0:
                continue
            results = {}
            for method in ['naive', 'ec_hte', 'ppci', 'ec_hte_ppci', 'global_corrected', 'oracle']:
                m = sub[sub['method'] == method]
                if len(m) == 0:
                    continue
                all_biases = pd.concat([m['bias_z0'].abs(), m['bias_z1'].abs()])
                avg_abs_bias = all_biases.mean()
                results[method] = avg_abs_bias

            naive = results.get('naive', 0)
            ec_hte = results.get('ec_hte', 0)
            ppci = results.get('ppci', 0)
            ec_hte_ppci = results.get('ec_hte_ppci', 0)

            # Check if close to paper values
