# Maybe the 0.179 is from a different aggregation. Let's try averaging bias (signed) then taking abs
c_both = df[df['dgp'] == 'C_both_errors']

print('Trying signed-mean-then-abs approach for C_both_errors:')
for regime in ['extreme', 'moderate', 'homogeneous']:
    for k in [2, 4]:
        for n in [50, 100, 250, 500]:
            sub = c_both[(c_both['regime'] == regime) & (c_both['k_subgroups'] == k) & (c_both['n_expert'] == n)]
            if len(sub) == 0:
                continue
            results = {}
            for method in ['naive', 'ec_hte', 'ppci', 'ec_hte_ppci']:
                m = sub[sub['method'] == method]
                if len(m) == 0:
                    continue
                # signed mean across subgroups, then abs, then avg z-levels
                signed_z0 = m['bias_z0'].mean()
                signed_z1 = m['bias_z1'].mean()
                v = (abs(signed_z0) + abs(signed_z1)) / 2
                results[method] = v

            naive = results.get('naive', 0)
            if abs(naive - 0.179) < 0.005 or abs(naive - 0.178) < 0.005:
                print(f'  MATCH: {regime} K={k} n={n}: naive={naive:.4f} ec_hte={results.get(\"ec_hte\",0):.4f} ppci={results.get(\"ppci\",0):.4f} ec_hte_ppci={results.get(\"ec_hte_ppci\",0):.4f}')

# Let me also try: perhaps it's from DGP A_covariate_only or B_outcome_only?
print()
print('Searching 0.179 in all DGPs with signed-mean-then-abs:')
for dgp in df['dgp'].unique():
    sub_dgp = df[df['dgp'] == dgp]
    for regime in sub_dgp['regime'].unique():
        for k in sub_dgp['k_subgroups'].unique():
            for n in sub_dgp['n_expert'].unique():
                sub = sub_dgp[(sub_dgp['regime'] == regime) & (sub_dgp['k_subgroups'] == k) & (sub_dgp['n_expert'] == n)]
                for method in sub['method'].unique():
                    m = sub[sub['method'] == method]
                    # Try various aggregation methods
                    v1 = pd.concat([m['bias_z0'].abs(), m['bias_z1'].abs()]).mean()
                    v2 = (abs(m['bias_z0'].mean()) + abs(m['bias_z1'].mean())) / 2
                    # Maybe max across z-levels, avg across subgroups
                    v3 = m[['bias_z0', 'bias_z1']].abs().max(axis=1).mean()

                    for v, label in [(v1, 'abs-mean'), (v2, 'mean-abs'), (v3, 'max-z-mean')]:
                        if abs(v - 0.179) < 0.002:
                            print(f'  {dgp} {regime} K={k} n={n} {method} ({label}): {v:.4f}')
